JS = r'''
const slides=[...document.querySelectorAll('.slide')];let current=0;
function show(n){current=Math.max(0,Math.min(slides.length-1,n));slides.forEach((s,i)=>{s.classList.toggle('active',i===current);s.setAttribute('aria-hidden',String(i!==current))});document.getElementById('count').textContent=`${current+1} / ${slides.length}`;document.getElementById('prev').disabled=current===0;document.getElementById('next').disabled=current===slides.length-1;document.querySelector('.progress').style.width=`${100*(current+1)/slides.length}%`;history.replaceState(null,'',`#${current+1}`)}
document.getElementById('prev').onclick=()=>show(current-1);document.getElementById('next').onclick=()=>show(current+1);document.getElementById('full').onclick=()=>{if(document.fullscreenElement)document.exitFullscreen?.();else document.documentElement.requestFullscreen?.()};document.addEventListener('keydown',e=>{if(e.altKey||e.ctrlKey||e.metaKey)return;if(['ArrowRight','PageDown',' '].includes(e.key)){e.preventDefault();show(current+1)}if(['ArrowLeft','PageUp'].includes(e.key)){e.preventDefault();show(current-1)}if(e.key==='Home')show(0);if(e.key==='End')show(slides.length-1)});show(Number(location.hash.slice(1)||1)-1);
'''

def slide(title, body, source='', cover=False):
    tag = 'h1' if cover else 'h2'
    return f'<section class="slide"><div class="eyebrow">TARIS · Магистерская диссертация · МГИМО</div><{tag}>{title}</{tag}>{body}' + (f'<div class="source">{source}</div>' if source else '') + '</section>'

def bullets(items):
    return '<ul>' + ''.join(f'<li>{x}</li>' for x in items) + '</ul>'

def note(text):
    return f'<p class="conclusion">{text}</p>'

