def write(name, title, slides):
    page = '<!doctype html><html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>' + escape(title) + '</title><style>' + CSS + '</style></head><body><main aria-label="Слайды презентации">' + ''.join(slides) + '</main><footer><button id="prev" aria-label="Предыдущий слайд">Назад</button><span id="count" aria-live="polite"></span><span class="hint">← → · Home / End · Печать: Ctrl+P</span><button id="full">Полный экран</button><button id="next" aria-label="Следующий слайд">Далее</button></footer><div class="progress"></div><script>' + JS + '</script></body></html>'
    (OUT / name).write_text(page, encoding='utf-8')

if __name__ == '__main__':
    OUT.mkdir(exist_ok=True)
    write('taris_pros_cons.html', 'TARIS — преимущества и ограничения', pros)
    write('taris_agent_method.html', 'TARIS — метод работы агента', method)
    print(f'Создано: {len(pros)} и {len(method)} слайдов; {OUT}')
